            <span class="field-error">@errors["FullName"]</span>
        }
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @onchange="e => Email = e.Value?.ToString() ?? """ />
        @if (errors.ContainsKey("Email"))
        {
            <span class="field-error">@errors["Email"]</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @onchange="e => Phone = e.Value?.ToString() ?? """ />
        @if (errors.ContainsKey("Phone"))
        {
            <span class="field-error">@errors["Phone"]</span>
        }
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" value="@Address" @onchange="e => Address = e.Value?.ToString() ?? """></textarea>
        @if (errors.ContainsKey("Address"))
        {
            <span class="field-error">@errors["Address"]</span>
        }
    </div>

    @if (isValidating)
    {
        <p class="validating-message">Validating email...</p>
    }

    <div class="step-buttons">
        <button type="button" class="btn-next" @onclick="HandleNext" disabled="@isValidating">Next</button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo? Info { get; set; }
    [Parameter] public EventCallback<PersonalInfo> OnCompleted { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string FullName = "";
    private string Email = "";
    private string Phone = "";
    private string Address = "";

    private Dictionary<string, string> errors = new();
    private bool isValidating;

    protected override void OnParametersSet()
    {
        if (Info is not null)
        {
            FullName = Info.FullName;
            Email = Info.Email;
            Phone = Info.Phone;
            Address = Info.Address;
        }
    }

    private async Task HandleNext()
    {
        errors.Clear();

        if (string.IsNullOrWhiteSpace(FullName))
            errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Email))
            errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Phone))
            errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Address))
            errors["Address"] = "Address is required.";

        if (errors.Count > 0) return;

        isValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                errors["Email"] = "This email address is not valid.";
                return;
            }
        }
        finally
        {
            isValidating = false;
        }

        await OnCompleted.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
    }
}
"}

{"path": "/tmp/sv-7797a72a476147b29061a002f3dc274d/Components/Pages/Apply/WorkHistoryStep.razor", "file_text": "@* Step 2: Work history with dynamic entries *@

<div class="step-content">
    <h2>Work History</h2>

    @for (int i = 0; i < entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@entries[index]"
                       Index="index"
                       CanRemove="@(entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn-add" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <p class="field-error">@errorMessage</p>
    }

    <div class="step-buttons">
        <button type="button" class="btn-back" @onclick="OnBack">Back</button>
        <button type="button" class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public WorkHistory? History { get; set; }
    [Parameter] public EventCallback<WorkHistory> OnCompleted { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<WorkEntry> entries = new();
    private string? errorMessage;

    protected override void OnParametersSet()
    {
        if (History is not null && History.Entries.Count > 0)
        {
            entries = History.Entries.ToList();
        }
        else if (entries.Count == 0)
        {
            entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
        }
    }

    private void AddEntry()
    {
        entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private void RemoveEntry(int index)
    {
        if (entries.Count > 1)
        {
            entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(int index, WorkEntry updated)
    {
        entries[index] = updated;
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        foreach (var entry in entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                errorMessage = "Each position must have a company name and job title.";
                return;
            }
        }

        await OnCompleted.InvokeAsync(new WorkHistory(entries.ToList()));
    }
}
"}

{"path": "/tmp/sv-7797a72a476147b29061a002f3dc274d/Components/Pages/Apply/ReferencesStep.razor", "file_text": "@* Step 3: References (2-3) *@

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < references.Count; i++)
    {
        var index = i;
        <div class="reference-card">
            <div class="reference-header">
                <h4>Reference @(index + 1)</h4>
                @if (references.Count > 2)
                {
                    <button type="button" class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="form-group">
                <label>Name *</label>
                <input type="text" value="@references[index].Name"
                       @onchange="e => UpdateReference(index, references[index] with { Name = e.Value?.ToString() ?? "" })" />
            </div>

            <div class="form-group">
                <label>Relationship *</label>
                <input type="text" value="@references[index].Relationship"
                       @onchange="e => UpdateReference(index, references[index] with { Relationship = e.Value?.ToString() ?? "" })" />
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@references[index].Email"
                           @onchange="e => UpdateReference(index, references[index] with { Email = e.Value?.ToString() ?? "" })" />
                </div>
                <div class="form-group">
                    <label>Phone</label>
                    <input type="tel" value="@references[index].Phone"
                           @onchange="e => UpdateReference(index, references[index] with { Phone = e.Value?.ToString() ?? "" })" />
                </div>
            </div>
        </div>
    }

    @if (references.Count < 3)
    {
        <button type="button" class="btn-add" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <p class="field-error">@errorMessage</p>
    }

    <div class="step-buttons">
        <button type="button" class="btn-back" @onclick="OnBack">Back</button>
        <button type="button" class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public EventCallback<List<Reference>> OnCompleted { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<Reference> references = new();
    private string? errorMessage;

    protected override void OnParametersSet()
    {
        if (References is not null && References.Count > 0)
        {
            references = References.ToList();
        }
        else if (references.Count == 0)
        {
            references.Add(new Reference("", "", "", ""));
            references.Add(new Reference("", "", "", ""));
        }
    }

    private void AddReference()
    {
        if (references.Count < 3)
        {
            references.Add(new Reference("", "", "", ""));
        }
    }

    private void RemoveReference(int index)
    {
        if (references.Count > 2)
        {
            references.RemoveAt(index);
        }
    }

    private void UpdateReference(int index, Reference updated)
    {
        references[index] = updated;
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        if (references.Count < 2)
        {
            errorMessage = "Please provide at least 2 references.";
            return;
        }

        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                errorMessage = "Each reference must have a name, relationship, and email.";
                return;
            }
        }

        await OnCompleted.InvokeAsync(references.ToList());
    }
}
"}

{"path": "/tmp/sv-7797a72a476147b29061a002f3dc274d/Components/Pages/Apply/CoverLetterStep.razor", "file_text": "@* Step 4: Cover letter with character count *@

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label>Write your cover letter *</label>
        <textarea rows="12"
                  maxlength="@MaxLength"
                  value="@coverLetter"
                  @oninput="e => coverLetter = e.Value?.ToString() ?? """></textarea>
        <span class="char-count @(coverLetter.Length > MaxLength ? "over-limit" : "")">
            @coverLetter.Length / @MaxLength characters
        </span>
    </div>

    @if (!string.IsNullOrEmpty(errorMessage))
    {
        <p class="field-error">@errorMessage</p>
    }

    <div class="step-buttons">
        <button type="button" class="btn-back" @onclick="OnBack">Back</button>
        <button type="button" class="btn-next" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<string> OnCompleted { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string coverLetter = "";
    private string? errorMessage;

    protected override void OnParametersSet()
    {
        if (CoverLetter is not null)
        {
            coverLetter = CoverLetter;
        }
    }

    private async Task HandleNext()
    {
        errorMessage = null;

        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            errorMessage = "A cover letter is required.";
            return;
        }

        if (coverLetter.Length > MaxLength)
        {
            errorMessage = $"Cover letter must not exceed {MaxLength} characters.";
            return;
        }

        await OnCompleted.InvokeAsync(coverLetter);
    }
}
"}

{"path": "/tmp/sv-7797a72a476147b29061a002f3dc274d/Components/Pages/Apply/ReviewStep.razor", "file_text": "@* Step 5: Review all data and submit *@

<div class="step-content">
    <h2>Review & Submit</h2>

    @if (IsSubmitted)
    {
        <div class="submission-confirmation">
            <h3>&#10003; Application Submitted Successfully!</h3>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-header">
                <h3>Personal Information</h3>
                <button type="button" class="btn-edit" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Full Name</dt><dd>@Personal?.FullName</dd>
                <dt>Email</dt><dd>@Personal?.Email</dd>
                <dt>Phone</dt><dd>@Personal?.Phone</dd>
                <dt>Address</dt><dd>@Personal?.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Work History</h3>
                <button type="button" class="btn-edit" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @if (Work?.Entries is not null)
            {
                @foreach (var entry in Work.Entries)
                {
                    <div class="review-entry">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <span class="review-dates">
                            @entry.StartDate.ToString("MMM yyyy") &ndash;
                            @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                        </span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>References</h3>
                <button type="button" class="btn-edit" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @if (References is not null)
            {
                @foreach (var r in References)
                {
                    <div class="review-entry">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        @r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $"| {r.Phone}" : "")
                    </div>
                }
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h3>Cover Letter</h3>
                <button type="button" class="btn-edit" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(errorMessage))
        {
            <p class="field-error">@errorMessage</p>
        }

        <div class="step-buttons">
            <button type="button" class="btn-back" @onclick="OnBack">Back</button>
            <button type="button" class="btn-submit" @onclick="HandleSubmit" disabled="@isSubmitting">
                @(isSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public WorkHistory? Work { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    private bool isSubmitting;
    private string? errorMessage;

    private async Task HandleSubmit()
    {
        errorMessage = null;
        isSubmitting = true;
        try
        {
            await OnSubmit.InvokeAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}
"}

