@* A single work history entry form *@

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company"
               @onchange="e => UpdateEntry(Entry with { Company = e.Value?.ToString() ?? "" })" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title"
               @onchange="e => UpdateEntry(Entry with { Title = e.Value?.ToString() ?? "" })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse(e.Value?.ToString() ?? DateTime.Today.ToString("yyyy-MM-dd")) })" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")"
                   disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value!.ToString()!) })" />
        </div>
        <div class="form-group checkbox-group">
            <label>
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(Entry with { Description = e.Value?.ToString() ?? "" })"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;

    private async Task UpdateEntry(WorkEntry updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }

    private async Task ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        await OnEntryChanged.InvokeAsync(updated);
    }
}

@* Step 1: Personal information *@

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@FullName" @onchange="e => FullName = e.Value?.ToString() ?? """ />
        @if (errors.ContainsKey("FullName"))
        {
            <span class="field-error">@errors["FullName"]</span>
        }
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Email" @onchange="e => Email = e.Value?.ToString() ?? """ />
        @if (errors.ContainsKey("Email"))
        {
            <span class="field-error">@errors["Email"]</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Phone" @onchange="e => Phone = e.Value?.ToString() ?? """ />
        @if (errors.ContainsKey("Phone"))
        {
