    opacity: 0.4;
    cursor: default;
}

.step-indicator .step.current .step-number {
    background: #4361ee;
    color: white;
    font-weight: bold;
}

.step-indicator .step.completed .step-number {
    background: #2ec4b6;
    color: white;
