    background: #fafafa;
    padding: 1rem;
    border-radius: 4px;
    border: 1px solid #e0e0e0;
}

/* Submission confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.submission-confirmation h3 {
    color: #2ec4b6;
    font-size: 1.5rem;
}

