arguments.new_str:
@* A single work history entry form *@

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="OnCompanyChanged" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="OnTitleChanged" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@FormatDate(Entry.StartDate)" @onchange="OnStartDateChanged" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@FormatNullableDate(Entry.EndDate)"
                   disabled="@IsCurrent"
                   @onchange="OnEndDateChanged" />
        </div>
        <div class="form-group checkbox-group">
            <label>
                <input type="checkbox" checked="@IsCurrent" @onchange="OnCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="OnDescriptionChanged"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null && Entry.StartDate != default;

    private string FormatDate(DateTime date) => date.ToString("yyyy-MM-dd");
    private string FormatNullableDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? string.Empty;

    private Task OnCompanyChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Company = e.Value?.ToString() ?? string.Empty });

    private Task OnTitleChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Title = e.Value?.ToString() ?? string.Empty });

    private Task OnStartDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        var date = string.IsNullOrEmpty(val) ? DateTime.Today : DateTime.Parse(val);
        return OnEntryChanged.InvokeAsync(Entry with { StartDate = date });
    }

    private Task OnEndDateChanged(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        DateTime? date = string.IsNullOrEmpty(val) ? null : DateTime.Parse(val);
        return OnEntryChanged.InvokeAsync(Entry with { EndDate = date });
    }

    private Task OnCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        return OnEntryChanged.InvokeAsync(updated);
    }

    private Task OnDescriptionChanged(ChangeEventArgs e) =>
        OnEntryChanged.InvokeAsync(Entry with { Description = e.Value?.ToString() ?? string.Empty });
}

